    if not digits.isascii() or not digits.isdigit():
        return None
    n = len(digits)

    if digits[0] == "4" and n in (13, 16, 19):
        brand = "Visa"
    elif n == 16 and (
        51 <= int(digits[:2]) <= 55 or 2221 <= int(digits[:4]) <= 2720
    ):
        brand = "Mastercard"
    elif n == 15 and digits[:2] in ("34", "37"):
        brand = "Amex"
